CREATE TABLE knowledge_objects(hash text PRIMARY KEY CHECK(hash ~ '^[a-f0-9]{64}$'),size_bytes integer NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE knowledge_spaces(id text PRIMARY KEY,title text NOT NULL,department_ids text[] NOT NULL DEFAULT '{}',revision integer NOT NULL DEFAULT 1);
CREATE TABLE knowledge_documents(id text PRIMARY KEY,space_id text NOT NULL REFERENCES knowledge_spaces(id),policy_code text NOT NULL,latest_counter integer NOT NULL DEFAULT 0,current_source_id text,UNIQUE(space_id,policy_code));
CREATE TABLE knowledge_sources(id text PRIMARY KEY,document_id text NOT NULL REFERENCES knowledge_documents(id),space_id text NOT NULL REFERENCES knowledge_spaces(id),title text NOT NULL,ordinal integer NOT NULL,version text NOT NULL,filename text NOT NULL,object_hash text NOT NULL REFERENCES knowledge_objects(hash),status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','withdrawn')),valid_from timestamptz NOT NULL,valid_until timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(document_id,version),UNIQUE(document_id,ordinal),UNIQUE(id,document_id),CHECK(valid_until IS NULL OR valid_until>valid_from));
ALTER TABLE knowledge_documents ADD CONSTRAINT current_source_belongs_to_document FOREIGN KEY(current_source_id,id) REFERENCES knowledge_sources(id,document_id);
CREATE TABLE knowledge_pages(id text PRIMARY KEY,space_id text NOT NULL REFERENCES knowledge_spaces(id),revision integer NOT NULL DEFAULT 0,published_revision_id text);
CREATE TABLE knowledge_revisions(id text PRIMARY KEY,page_id text NOT NULL REFERENCES knowledge_pages(id),page_revision integer NOT NULL,title text NOT NULL,body_hash text NOT NULL REFERENCES knowledge_objects(hash),source_ids text[] NOT NULL,citations jsonb NOT NULL,state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','reviewed','published')),reviewed_by text REFERENCES principals(id),reviewer_credential_id text REFERENCES credentials(id),reviewer_epoch integer,review_hash text,reviewed_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(page_id,page_revision),UNIQUE(id,page_id));
ALTER TABLE knowledge_pages ADD CONSTRAINT published_revision_belongs_to_page FOREIGN KEY(published_revision_id,id) REFERENCES knowledge_revisions(id,page_id);
CREATE TABLE knowledge_evidence(revision_id text NOT NULL REFERENCES knowledge_revisions(id),source_id text NOT NULL REFERENCES knowledge_sources(id),PRIMARY KEY(revision_id,source_id));
CREATE TABLE knowledge_publications(id text PRIMARY KEY,page_id text NOT NULL REFERENCES knowledge_pages(id),revision_id text NOT NULL REFERENCES knowledge_revisions(id),publisher_id text NOT NULL REFERENCES principals(id),approval_id text NOT NULL REFERENCES product_approvals(id),state text NOT NULL CHECK(state IN ('published','withdrawn')),created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX knowledge_source_space ON knowledge_sources(space_id,id);
CREATE INDEX knowledge_page_space ON knowledge_pages(space_id,id);
CREATE INDEX knowledge_source_dependencies ON knowledge_revisions USING gin(source_ids);

CREATE TABLE knowledge_reviews(id text PRIMARY KEY,revision_id text NOT NULL REFERENCES knowledge_revisions(id),reviewer_id text NOT NULL REFERENCES principals(id),decision text NOT NULL,reason text NOT NULL,review_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
